async function run(input){const action=String(input.action||'');if(action==='list_factor_templates'){const value=await call('/api/strategy/factor-templates');return{status:'succeeded',templates:(value.templates||[]).map(item=>({id:item.id,label:item.label,category:item.category,description:item.description,inputs:item.inputs,requirements:item.requirements,recommended_direction:item.recommended_direction}))}}const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');if(action==='get')return readProject(id,input);if(action==='delete'){if(input.confirm_delete!==true)throw new Error('Deleting a research project requires explicit confirmation');await call('/api/strategy/projects/'+encodeURIComponent(id)+'?confirm_delete=true',{method:'DELETE'});return{status:'succeeded',deleted:true,project_id:id}}if(input.confirm_write!==true)throw new Error('Project mutation requires confirm_write=true');if(action==='create'){if(input.confirm_python_execution!==true)throw new Error('Project creation validates trusted local Python and requires confirmation');if(!input.name||!input.strategy_source)throw new Error('name and complete strategy_source are required');const factors=Array.isArray(input.factor_sources)?input.factor_sources:[],project=await call('/api/strategy/projects',{method:'POST',body:JSON.stringify({project_id:id,name:String(input.name),description:String(input.description||''),strategy_source:String(input.strategy_source),factor_sources:factors.map(String),profile:'runtime',settings:input.settings||{},confirm_save:true,confirm_python_execution:true})});return writeResult(project,['strategy.py',...(project.source_units||[]).filter(item=>item.kind==='factor').map(item=>item.path)])}if(action==='clone'){if(input.confirm_python_execution!==true)throw new Error('Project creation validates trusted local Python and requires confirmation');if(!input.name||!input.source_project_id)throw new Error('name and source_project_id are required for clone');const project=await call('/api/strategy/projects/'+encodeURIComponent(String(input.source_project_id))+'/clone',{method:'POST',body:JSON.stringify({target_id:id,name:String(input.name),confirm_save:true,confirm_python_execution:true})});return writeResult(project,(project.source_units||[]).map(item=>item.path))}if(action==='update_metadata'){const current=await call('/api/strategy/projects/'+encodeURIComponent(id)),project=await call('/api/strategy/projects/'+encodeURIComponent(id)+'/metadata',{method:'PUT',body:JSON.stringify({name:input.name||current.name,description:input.description===undefined?current.description:String(input.description),profile:'runtime',settings:input.settings||current.settings,confirm_write:true})});return{status:'succeeded',project_id:id,revision:project.current_revision,changed_files:[],metadata_changed:true}}throw new Error('unsupported research project action')}
